INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66138915', 66138915, 'analyze_legacy', 'Badan Gizi Nasional', 'central', 'BADAN GIZI NASIONAL', 'Media Monitoring Berita', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 500000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '10 Pkt', 'Media Monitoring Berita', '1) Tahapan Persiapan (Pra-Produksi) • Kick-off Meeting antara BGN dan penyedia jasa. • Penyusunan daftar kata kunci (keyword monitoring). • Penetapan parameter analisis (tone, isu, reach, media value). • Penyiapan sistem dashboard monitoring. 2) Tahapan Pelaksanaan • Monitoring berita harian selama bulan Maret – Desember 2026. • Kliping dan dokumentasi berita dalam format digital. • Klasifikasi berdasarkan jenis media dan sentimen. • Penyusunan rekap harian dan distribusi kepada Biro Hukum dan Humas. • Penyusunan laporan mingguan berisi analisis tren isu. • Penyusunan laporan bulanan (analisis komprehensif dan evaluatif). 3) Tahapan Finalisasi dan Pelaporan • Penyusunan laporan akhir periode kontrak. • Analisis tren pemberitaan selama 10 bulan. • Rekomendasi strategi komunikasi berdasarkan hasil monitoring. • Serah terima laporan lengkap dalam bentuk softcopy dan hardcopy.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2581206);
