INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66188717', 66188717, 'analyze_legacy', 'Provinsi Sulawesi Tengah', 'provinsi', 'Dinas Perumahan, Kawasan Permukiman dan Pertanahan Provinsi Sulawesi Tengah', 'PengawasanTeknis Jalan Lingkungan Desa Tintingan,Desa Bone Balantak, Desa Bahotokong,Kel. Kalaka,Desa Bone Baru', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Sulawesi Tengah, Banggai (Kab.)', 34380000, 'August 2026', 'APBD', 1, 1, '1 Paket', 'URAIAN SINGKAT LINGKUP PEKERJAAN JASA KONSULTANSI PENGAWAN TEKNIS JALAN LINGKUNGAN 1. Lingkup Kegiatan a. Melaksanakan konsultansi dan koordinasi kepada Dinas Perumahan Kawasan Permukiman dan Pertanahan Provinsi Sulawesi Tengah selaku Pemberi Tugas . b. Mengawasi pelaksanaan fisik secara aktif dan terus menerus dari tahap persiapan pelaksanaan, pelaksanaan pembangunan sampai penyerahan fisik, yang meliputi kegiatan pengendalian jadwal, kualitas dan kuantitas pekerjaan sesuai dengan rencana yang telah ditentukan. c. Menjalankan ketentuan – ketentuan pelaksanaan pekejaan yang telah ditetapkan dalam Dokumen Perencanaan Teknis. d. Menunjukkan kepada pelaksana fisik, patok-patok dan titik-titik ikat pematokan pelaksanaan. Letak patok-patok dilokasi ditentukan oleh perencana dan akan ditunjukkan kepada Supervisi pada waktu akan memulai pekerjaan. e. Atas nama instansi memberikan instruksi-instruksi yang perlu kepada pelaksana fisik, dan memberikan serta mengontrol pekerjaan untuk menjamin pelaksanaan sesuai dengan kontrak. f. Selama waktu pelaksanaan melaksanakan pengawasan diseluruh lapangan pekerjaan dan hal-hal yang berkaitan dengan kepentingan konservasi tanah / air pengujian material untuk konstruksi. g. Bersama – sama pelaksana fisik memastikan pengukuran dan menyepakati hasil pekerjaan sesuai dengan yang tercantum didalam kontrak pelaksanaan fisik. h. Mencatat semua hasil pengukuran volume pekerjaan yang diperlukan untuk pembayaran dengan menggunakan formulir yang lazim dan disetujui oleh kegiatan. a. Bersama-sama pelaksana fisik menyiapkan dan menyepakati setiap perubahan dari bagian pekerjaan (change order) berikut spesifikasi dan gambar-gambar rencana yang bersangkutan. j. Memeriksa semua gambar kerja (shop drawing) yang dibuat oleh pelaksana fisik untuk diajukan kepada pemilik pekerjaan guna disahkan. k. Mengingatkan Pemberi Tugas atas setiap persoalan yang timbul sehubungan dengan kontrak dan memberikan rekomendasi cara penyelesaiannya. l. Mengevaluasi semua tuntutan pembayaran tambahan atau perpanjangan waktu yang diajukan oleh pelaksana fisik dan memberikan rekomendasi kepada Pemberi Tugas. m. Membantu Pemberi Tugas dalam menyelesaikan setiap perbedaan pendapat dan memberikan pendapat yang mantap untuk setiap tuntutan yang diajukan oleh pelaksana fisik. Hal ini dilakukan dengan laporan tertulis disertai analisa yang mengandung dasar-dasar pertimbangan. n. Melaksanakan pemeriksaaan secara periodik terhadap material atau bahan – bahan yang digunakan oleh Kontraktor, dan memberi rekomendasi persetujuan materail/bahan yang dapat digunakan sesuai dengan persyaratan teknis yang telah ditentukan. o. Melakukan inspeksi dan membuat rekomendasi pekerjaan atas pekerjaan pelaksanaan fisik yang telah diselesaikan secara lengkap agar dapat dinyatakan diterima baik oleh Pemberi Tugas guna menetapkan dimulainya masa pemeliharaan p. Pembuatan jadwal kegiatan/rencana kerja secara rinci dalam jangka waktu yang ditetapkan q. Melakukan Konsultansi secara berkala kepada Pemberi Tugas. 2. Keluaran Keluaran/output yang dihasilkan dari pekerjaan ini adalah sebagai berikut : Konsultan Pengawas wajib membuat laporan - laporan yang berpedoman pada jenis, bentuk dan sistematika, penjabaran dari distribusi pelaporan seperti yang dijelaskan di bawah ini. Laporan-laporan yang perlu disiapkan adalah: a) Laporan Mingguan b) Laporan Bulanan c) Poto Dokumentasi Fisik+LaporanAkhir d) Laporan lain-lain Soft Copy Semua file yang dihasilkan dari pekerjaan ini yang terdiri dari dokumen perencanaan, pelaporan dan data penunjang termasuk dokumentasi serta hasil survei lapangan dibuat dalam bentuk soft copy yang dimuat ke dalam perangkat penyimpanan eksternal (format file data mentah : .docx, .xlxs, .dwg, .jpg, .png). Format pelaporan harus mengikuti standar format produk yang telah ditetapkan (buku laporan dalam format A4, Dokumen Gambar dalam format A3).', 'Jasa Konsultansi Pengawasan Teknis Jalan Lingkungan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2586869);
